'use strict';
const http = require('node:http');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const REPO = '<run-project>';
const { createApp } = require(REPO + '/src/app');
const { paginate } = require(REPO + '/src/lib/pagination');
const { sumLines } = require(REPO + '/src/lib/money');

function call(port, method, urlPath, { body, token } = {}) {
  return new Promise((resolve, reject) => {
    const payload = body === undefined ? undefined : JSON.stringify(body);
    const headers = {};
    if (payload !== undefined) headers['content-type'] = 'application/json';
    if (token) headers.authorization = `Bearer ${token}`;
    const req = http.request({ host: '127.0.0.1', port, method, path: urlPath, headers, agent: false }, (res) => {
      const chunks = [];
      res.on('data', (c) => chunks.push(c));
      res.on('end', () => {
        const text = Buffer.concat(chunks).toString('utf8');
        const isJson = (res.headers['content-type'] || '').startsWith('application/json');
        resolve({ status: res.statusCode, body: isJson && text ? JSON.parse(text) : undefined, text });
      });
    });
    req.on('error', reject);
    req.end(payload);
  });
}

(async () => {
  const reportDir = fs.mkdtempSync(path.join(os.tmpdir(), 'probe-reports-'));
  const ADMIN = { email: 'admin@example.com', password: 'admin-password', name: 'Admin' };
  const app = createApp({ secret: 'test-secret', reportDir, admin: ADMIN });
  const port = await app.listen(0);
  const c = (m, p, o) => call(port, m, p, o);
  const login = async (email, password) => (await c('POST', '/sessions', { body: { email, password } })).body.token;
  const signUp = async (email) => {
    await c('POST', '/users', { body: { email, password: 'correct-horse', name: 'C' } });
    return login(email, 'correct-horse');
  };
  const adminToken = await login(ADMIN.email, ADMIN.password);
  const alice = await signUp('alice@example.com');
  const bob = await signUp('bob@example.com');

  const order = (await c('POST', '/orders', { token: alice, body: { items: [{ sku: 'X', unitPrice: 10, quantity: 1 }] } })).body;

  // PROBE 1: IDOR — bob reads alice's order
  const idor = await c('GET', `/orders/${order.id}`, { token: bob });
  console.log('PROBE1 idor GET /orders/:id as non-owner ->', idor.status, JSON.stringify(idor.body));

  // PROBE 2: path traversal on report download
  fs.writeFileSync(path.join(reportDir, '..', 'probe-secret.txt'), 'TOP-SECRET');
  const trav = await c('GET', '/reports/..%2Fprobe-secret.txt', { token: adminToken });
  console.log('PROBE2 traversal GET /reports/..%2Fprobe-secret.txt ->', trav.status, JSON.stringify(trav.text));

  // PROBE 3: totalPages
  console.log('PROBE3 paginate(25 items, pageSize 20).totalPages ->', paginate(Array(25).fill(0), { pageSize: '20' }).totalPages, '(expected 2)');
  console.log('PROBE3 paginate(0 items).totalPages ->', paginate([], {}).totalPages, '(expected 1)');

  // PROBE 4: shipped order can be cancelled
  const o2 = (await c('POST', '/orders', { token: alice, body: { items: [{ sku: 'Y', unitPrice: 5, quantity: 1 }] } })).body;
  await c('POST', '/payments', { token: alice, body: { orderId: o2.id, amount: 5 } });
  await c('POST', `/orders/${o2.id}/ship`, { token: adminToken });
  const cancelShipped = await c('POST', `/orders/${o2.id}/cancel`, { token: alice });
  console.log('PROBE4 cancel a shipped order ->', cancelShipped.status, JSON.stringify(cancelShipped.body));

  // PROBE 5: float total
  console.log('PROBE5 sumLines(0.1 x3) ->', sumLines([{ unitPrice: 0.1, quantity: 3 }]));
  const o3 = (await c('POST', '/orders', { token: alice, body: { items: [{ sku: 'Z', unitPrice: 0.1, quantity: 3 }, { sku: 'W', unitPrice: 0.2, quantity: 1 }] } })).body;
  console.log('PROBE5 stored order.total ->', o3.total, '(expected 0.5)');
  const pay = await c('POST', '/payments', { token: alice, body: { orderId: o3.id, amount: 0.5 } });
  console.log('PROBE5 paying 0.5 for that order ->', pay.status, JSON.stringify(pay.body));

  await app.close();
  fs.rmSync(reportDir, { recursive: true, force: true });
  fs.rmSync(path.join(reportDir, '..', 'probe-secret.txt'), { force: true });
})();
EOF
