const fs = require('fs'), path = require('path');
const ROOT = process.argv[2];
const files = [];
(function walk(d) {
  for (const e of fs.readdirSync(d, { withFileTypes: true })) {
    const p = path.join(d, e.name);
    if (e.isDirectory()) walk(p);
    else if (p.endsWith('.js')) files.push(p.split(path.sep).join('/'));
  }
})(path.join(ROOT, 'src'));
const rel = (f) => f.slice(f.indexOf('/src/') + 1);
const edges = [];
for (const f of files) {
  const src = fs.readFileSync(f, 'utf8');
  for (const m of src.matchAll(/require\('(\.[^']+)'\)/g)) {
    let t = path.posix.normalize(path.posix.join(path.posix.dirname(f), m[1]));
    if (!t.endsWith('.js')) t += '.js';
    edges.push([rel(f), rel(t)]);
  }
}
console.log('Subsystem-count (files) =', files.length);
console.log('Dependency-edges (internal requires) =', edges.length);
const adj = {};
for (const [a, b] of edges) (adj[a] = adj[a] || []).push(b);
const memo = {};
let cycle = false;
function depth(u, stack) {
  if (stack.has(u)) { cycle = true; console.log('CYCLE:', [...stack, u].join(' -> ')); return 0; }
  if (memo[u] !== undefined) return memo[u];
  stack.add(u);
  let d = 0;
  for (const v of adj[u] || []) d = Math.max(d, 1 + depth(v, stack));
  stack.delete(u);
  return (memo[u] = d);
}
let max = 0, arg = '';
for (const f of files) { const d = depth(rel(f), new Set()); if (d > max) { max = d; arg = rel(f); } }
console.log('Max-chain-depth (hops) =', max, 'longest from', arg);
console.log('Static cycle =', cycle ? 'FAIL' : 'Pass');
console.log('--- edges ---');
for (const [a, b] of edges.slice().sort()) console.log(' ', a, '->', b);
EOF
