     6	
     7	const TRANSITIONS = {
     8	  pending: ['paid', 'cancelled'],
     9	  paid: ['shipped', 'cancelled'],
    10	  shipped: ['delivered'],
    11	  delivered: [],
    12	  cancelled: [],
    13	};
    14	
    15	function normalizeItems(items) {
    16	  if (!Array.isArray(items) || items.length === 0) throw invalid('an order needs at least one item');
    17	  return items.map((item) => {
    18	    if (!item || typeof item.sku !== 'string' || item.sku.trim() === '') throw invalid('every item needs a sku');
    19	    if (!isAmount(item.unitPrice)) throw invalid('unitPrice must be a positive amount with at most two decimals');
    20	    if (!Number.isInteger(item.quantity) || item.quantity < 1) throw invalid('quantity must be a positive integer');
    21	    return { sku: item.sku.trim(), unitPrice: item.unitPrice, quantity: item.quantity };
    22	  });
    23	}
    24	
    25	function createOrderService({ store }) {
    26	  function create(user, { items }) {
    27	    const lines = normalizeItems(items);
    28	    return store.insert('orders', {
    29	      userId: user.id,
    30	      items: lines,
    31	      total: fromCents(itemsTotalCents(lines)),
    32	      status: 'pending',
    33	      createdAt: new Date().toISOString(),
    34	    });
    35	  }
    36	
    37	  // Not exposed: every caller outside this service must name the actor, so that
    38	  // an order read cannot skip the ownership check in getOwned.
    39	  function get(id) {
    40	    const order = store.get('orders', id);
    41	    if (!order) throw notFound('order not found');
    42	    return order;
    43	  }
    44	
    45	  function getOwned(user, id) {
    46	    const order = get(id);
    47	    if (user.role !== 'admin' && order.userId !== user.id) throw notFound('order not found');
    48	    return order;
    49	  }
    50	
    51	  function list(user, query) {
    52	    const visible = store.list('orders', (order) => user.role === 'admin' || order.userId === user.id);
    53	    return paginate(visible, query);
    54	  }
    55	
    56	  function all() {
    57	    return store.list('orders');
    58	  }
    59	
    60	  function transition(order, next, patch = {}) {
    61	    if (!TRANSITIONS[order.status].includes(next)) {
    62	      throw conflict(`order cannot move from ${order.status} to ${next}`);
    63	    }
    64	    return store.update('orders', order.id, { ...patch, status: next, updatedAt: new Date().toISOString() });
    65	  }
    66	
    67	  return {
    68	    create,
    69	    getOwned,
    70	    list,
    71	    all,
    72	    cancel: (user, id) => transition(getOwned(user, id), 'cancelled'),
    73	    ship: (id) => transition(get(id), 'shipped'),
    74	    deliver: (id) => transition(get(id), 'delivered'),
    75	    markPaid: (id, paymentId) => transition(get(id), 'paid', { paymentId }),
    76	  };
    77	}
