     1	'use strict';
     2	
     3	const crypto = require('node:crypto');
     4	const { invalid, conflict } = require('../lib/errors');
     5	const { paginate } = require('../lib/pagination');
     6	
     7	const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
     8	const MIN_PASSWORD_LENGTH = 8;
     9	
    10	function hashPassword(password, salt) {
    11	  return crypto.scryptSync(password, salt, 32).toString('hex');
    12	}
    13	
    14	function normalizeEmail(email) {
    15	  return typeof email === 'string' ? email.trim().toLowerCase() : '';
    16	}
    17	
    18	function toPublic(user) {
    19	  return { id: user.id, email: user.email, name: user.name, role: user.role, createdAt: user.createdAt };
    20	}
    21	
    22	function createUserService({ store }) {
    23	  function register({ email, password, name }, role = 'customer') {
    24	    const normalized = normalizeEmail(email);
    25	    if (!EMAIL_PATTERN.test(normalized)) throw invalid('a valid email is required');
    26	    if (typeof password !== 'string' || password.length < MIN_PASSWORD_LENGTH) {
    27	      throw invalid(`password must be at least ${MIN_PASSWORD_LENGTH} characters`);
    28	    }
    29	    if (typeof name !== 'string' || name.trim() === '') throw invalid('name is required');
    30	    if (store.findOne('users', (user) => user.email === normalized)) throw conflict('email already registered');
    31	    const salt = crypto.randomBytes(16).toString('hex');
    32	    return toPublic(store.insert('users', {
    33	      email: normalized,
    34	      name: name.trim(),
    35	      role,
    36	      salt,
    37	      passwordHash: hashPassword(password, salt),
    38	      createdAt: new Date().toISOString(),
    39	    }));
    40	  }
    41	
    42	  function verifyCredentials(email, password) {
    43	    if (typeof password !== 'string') return null;
    44	    const normalized = normalizeEmail(email);
    45	    const user = store.findOne('users', (candidate) => candidate.email === normalized);
    46	    if (!user) return null;
    47	    const expected = Buffer.from(user.passwordHash, 'hex');
    48	    const actual = Buffer.from(hashPassword(password, user.salt), 'hex');
    49	    return crypto.timingSafeEqual(expected, actual) ? toPublic(user) : null;
    50	  }
    51	
    52	  function list(query) {
    53	    return paginate(store.list('users').map(toPublic), query);
    54	  }
    55	
    56	  function find(id) {
    57	    const user = store.get('users', id);
    58	    return user ? toPublic(user) : null;
    59	  }
    60	
    61	  return { register, verifyCredentials, list, find };
    62	}
    63	
    64	module.exports = { createUserService };
