'use strict';
const fs = require('node:fs');
const http = require('node:http');
const os = require('node:os');
const path = require('node:path');

function makeDriver(appPath) {
  const { createApp } = require(appPath);
  return async function start(options = {}) {
    const reportDir = fs.mkdtempSync(path.join(os.tmpdir(), 'av-reports-'));
    const app = createApp({ secret: 'test-secret', reportDir,
      admin: { email: 'admin@example.com', password: 'admin-password', name: 'Admin' }, ...options });
    const port = await app.listen(0);
    function call(method, urlPath, { body, token, rawPath } = {}) {
      return new Promise((resolve, reject) => {
        const payload = body === undefined ? undefined : JSON.stringify(body);
        const headers = {};
        if (payload !== undefined) headers['content-type'] = 'application/json';
        if (token) headers.authorization = `Bearer ${token}`;
        const req = http.request({ host: '127.0.0.1', port, method, path: rawPath || urlPath, headers, agent: false }, (res) => {
          const chunks = [];
          res.on('data', (c) => chunks.push(c));
          res.on('end', () => {
            const text = Buffer.concat(chunks).toString('utf8');
            const isJson = (res.headers['content-type'] || '').startsWith('application/json');
            resolve({ status: res.statusCode, headers: res.headers, body: isJson && text ? JSON.parse(text) : undefined, text });
          });
        });
        req.on('error', reject);
        req.end(payload);
      });
    }
    async function login(email, password = 'correct-horse') {
      return (await call('POST', '/sessions', { body: { email, password } })).body.token;
    }
    async function signUp(email, extra = {}) {
      const r = await call('POST', '/users', { body: { email, password: 'correct-horse', name: 'C', ...extra } });
      return { token: await login(email), profile: r.body, raw: r };
    }
    return { call, login, signUp, reportDir,
      adminToken: await login('admin@example.com', 'admin-password'),
      stop: () => app.close().then(() => fs.rmSync(reportDir, { recursive: true, force: true })) };
  };
}
module.exports = { makeDriver };
