'use strict';
const assert = require('node:assert/strict');
const { makeDriver } = require('./drive');
const REPO = '<run-project>';
const start = makeDriver(REPO + '/src/app.js');
const out = [];
const ok = (name, cond, detail) => out.push(`${cond ? 'PASS' : 'FAIL'} ${name}${detail ? ' :: ' + detail : ''}`);

(async () => {
  // --- (a) ownership on GET /orders/:id
  {
    const s = await start();
    const alice = await s.signUp('alice@example.com');
    const bob = await s.signUp('bob@example.com');
    const order = (await s.call('POST', '/orders', { token: alice.token, body: { items: [{ sku: 'X', unitPrice: 10, quantity: 1 }] } })).body;
    const asBob = await s.call('GET', `/orders/${order.id}`, { token: bob.token });
    ok('a: foreign read 404', asBob.status === 404, `status=${asBob.status}`);
    ok('a: foreign read body', JSON.stringify(asBob.body) === '{"error":"order not found"}', JSON.stringify(asBob.body));
    ok('a: no leakage in body', !asBob.text.includes(alice.profile.id) && !asBob.text.includes(order.id), asBob.text);
    const asOwner = await s.call('GET', `/orders/${order.id}`, { token: alice.token });
    ok('a: owner 200', asOwner.status === 200 && asOwner.body.id === order.id, `status=${asOwner.status}`);
    const asAdmin = await s.call('GET', `/orders/${order.id}`, { token: s.adminToken });
    ok('a: admin 200', asAdmin.status === 200 && asAdmin.body.id === order.id, `status=${asAdmin.status}`);
    const unknown = await s.call('GET', '/orders/does-not-exist', { token: bob.token });
    ok('a: unknown id 404 same body', unknown.status === 404 && unknown.body.error === 'order not found', `${unknown.status} ${JSON.stringify(unknown.body)}`);
    // other order-scoped routes
    const cancelByBob = await s.call('POST', `/orders/${order.id}/cancel`, { token: bob.token });
    ok('a: foreign cancel 404', cancelByBob.status === 404, `status=${cancelByBob.status}`);
    const payByBob = await s.call('POST', '/payments', { token: bob.token, body: { orderId: order.id, amount: 10 } });
    ok('a: foreign pay 404', payByBob.status === 404, `status=${payByBob.status}`);
    // admin-only ship/deliver still bypass ownership legitimately
    const shipByBob = await s.call('POST', `/orders/${order.id}/ship`, { token: bob.token });
    ok('a: foreign ship 403', shipByBob.status === 403, `status=${shipByBob.status}`);
    await s.stop();
  }

  // --- (c) lifecycle
  {
    const s = await start();
    const alice = await s.signUp('alice@example.com');
    const mk = async () => (await s.call('POST', '/orders', { token: alice.token, body: { items: [{ sku: 'X', unitPrice: 10, quantity: 1 }] } })).body;
    const pay = (id) => s.call('POST', '/payments', { token: alice.token, body: { orderId: id, amount: 10 } });

    let o = await mk();
    ok('c: ship pending -> 409', (await s.call('POST', `/orders/${o.id}/ship`, { token: s.adminToken })).status === 409);
    ok('c: deliver pending -> 409', (await s.call('POST', `/orders/${o.id}/deliver`, { token: s.adminToken })).status === 409);
    ok('c: cancel pending -> 200', (await s.call('POST', `/orders/${o.id}/cancel`, { token: alice.token })).status === 200);
    ok('c: cancel cancelled -> 409', (await s.call('POST', `/orders/${o.id}/cancel`, { token: alice.token })).status === 409);
    ok('c: pay cancelled -> 409', (await pay(o.id)).status === 409);

    o = await mk();
    ok('c: pay pending -> 201', (await pay(o.id)).status === 201);
    ok('c: cancel paid -> 200 (README allows)', (await s.call('POST', `/orders/${o.id}/cancel`, { token: alice.token })).status === 200);

    o = await mk(); await pay(o.id);
    ok('c: deliver paid -> 409', (await s.call('POST', `/orders/${o.id}/deliver`, { token: s.adminToken })).status === 409);
    ok('c: ship paid -> 200', (await s.call('POST', `/orders/${o.id}/ship`, { token: s.adminToken })).status === 200);
    const cs = await s.call('POST', `/orders/${o.id}/cancel`, { token: alice.token });
    ok('c: cancel shipped -> 409', cs.status === 409, `${cs.status} ${JSON.stringify(cs.body)}`);
    ok('c: ship shipped -> 409', (await s.call('POST', `/orders/${o.id}/ship`, { token: s.adminToken })).status === 409);
    ok('c: deliver shipped -> 200', (await s.call('POST', `/orders/${o.id}/deliver`, { token: s.adminToken })).status === 200);
    const cd = await s.call('POST', `/orders/${o.id}/cancel`, { token: alice.token });
    ok('c: cancel delivered -> 409', cd.status === 409, `${cd.status} ${JSON.stringify(cd.body)}`);
    ok('c: deliver delivered -> 409', (await s.call('POST', `/orders/${o.id}/deliver`, { token: s.adminToken })).status === 409);
    ok('c: status still delivered', (await s.call('GET', `/orders/${o.id}`, { token: alice.token })).body.status === 'delivered');
    // ADMIN cancelling a customer order (README says the customer may cancel)
    const o2 = await mk();
    const adminCancel = await s.call('POST', `/orders/${o2.id}/cancel`, { token: s.adminToken });
    out.push(`INFO c: admin cancel of a customer order -> ${adminCancel.status} (${JSON.stringify(adminCancel.body && adminCancel.body.status)})`);
    await s.stop();
  }

  // --- (d) money exactness end to end + CSV
  {
    const s = await start();
    const alice = await s.signUp('alice@example.com');
    const cases = [];
    const prices = [0.1, 0.2, 0.3, 0.07, 1.15, 8.6, 2.675, 0.29, 4.35, 1.005, 9.99, 0.01, 1234.56, 70.7];
    for (const p of prices) for (const q of [1, 3, 7, 11, 13, 97]) cases.push([p, q]);
    let bad = 0, rejected = 0;
    for (const [p, q] of cases) {
      const res = await s.call('POST', '/orders', { token: alice.token, body: { items: [{ sku: 'X', unitPrice: p, quantity: q }] } });
      if (res.status !== 201) { rejected += 1; out.push(`INFO d: ${p} x ${q} rejected ${res.status} ${JSON.stringify(res.body)}`); continue; }
      const expectCents = Math.round(p * 100) * q;
      const total = res.body.total;
      const exact = Math.abs(total * 100 - expectCents) < 1e-9 && String(total) === String(expectCents / 100);
      if (!exact) { bad += 1; out.push(`FAIL d: ${p} x ${q} -> total ${total} (JSON ${JSON.stringify(res.text.match(/"total":[^,}]*/))}) expected ${expectCents/100}`); }
      const pay = await s.call('POST', '/payments', { token: alice.token, body: { orderId: res.body.id, amount: total } });
      if (pay.status !== 201) { bad += 1; out.push(`FAIL d: payment of exact total ${total} rejected ${pay.status} ${JSON.stringify(pay.body)}`); }
    }
