    ok('d: raw JSON has no float noise', /"total":60\.7[,}]/.test(multi.text), multi.text.slice(0, 200));
    // CSV export
    const name = (await s.call('POST', '/reports/orders', { token: s.adminToken })).body.name;
    const csv = await s.call('GET', `/reports/${name}`, { token: s.adminToken });
    const lines = csv.text.trim().split('\n');
    const bads = lines.slice(1).map((l) => l.split(',')[3]).filter((v) => !/^\d+\.\d{2}$/.test(v));
    ok('d: every CSV total is a plain 2-decimal number', bads.length === 0, bads.join('|'));
    const csvForMulti = lines.find((l) => l.startsWith(multi.body.id));
    ok('d: CSV total for multi-line order is 60.70', csvForMulti && csvForMulti.split(',')[3] === '60.70', String(csvForMulti));
    await s.stop();
  }

  // --- router behaviour
  {
    const s = await start();
    const alice = await s.signUp('alice@example.com');
    const r1 = await s.call('DELETE', '/orders', { token: alice.token });
    ok('r: DELETE /orders -> 405', r1.status === 405, `${r1.status} ${JSON.stringify(r1.body)}`);
    const r2 = await s.call('GET', '/nope', { token: alice.token });
    ok('r: unknown route -> 404', r2.status === 404, `${r2.status} ${JSON.stringify(r2.body)}`);
    const r3 = await s.call('PUT', '/users/me', { token: alice.token });
    ok('r: PUT /users/me -> 405', r3.status === 405, `${r3.status} ${JSON.stringify(r3.body)}`);
    const r4 = await s.call('GET', '/reports/orders', { token: s.adminToken });
    ok('r: GET /reports/orders -> 404 (name allowlist)', r4.status === 404, `${r4.status} ${JSON.stringify(r4.body)}`);
    const r5 = await s.call('POST', '/reports/orders-1-abcdef.csv', { token: s.adminToken });
    ok('r: POST /reports/<name> -> 405', r5.status === 405, `${r5.status} ${JSON.stringify(r5.body)}`);
    const r6 = await s.call('GET', '/orders/%ZZ', { token: alice.token, rawPath: '/orders/%ZZ' });
    ok('r: malformed percent escape -> 400', r6.status === 400, `${r6.status} ${JSON.stringify(r6.body)}`);
