    // trailing slash / empty segments
    const o = (await s.call('POST', '/orders', { token: alice.token, body: { items: [{ sku: 'X', unitPrice: 1, quantity: 1 }] } })).body;
    const r8 = await s.call('GET', `/orders/${o.id}/`, { token: alice.token });
    out.push(`INFO r: trailing slash GET /orders/:id/ -> ${r8.status}`);
    const r9 = await s.call('GET', `//orders//${o.id}`, { token: alice.token, rawPath: `//orders//${o.id}` });
    out.push(`INFO r: doubled slashes -> ${r9.status}`);
    await s.stop();
