  {
    const s = await start();
    const esc = await s.signUp('evil@example.com', { role: 'admin' });
    ok('x: role in POST /users ignored', esc.profile.role === 'customer', String(esc.profile.role));
    const listed = await s.call('GET', '/users', { token: esc.token });
    ok('x: escalation attempt still 403 on /users', listed.status === 403, String(listed.status));
    const me = await s.call('GET', '/users/me', { token: esc.token });
    ok('x: /users/me exposes no secret material', me.body && me.body.passwordHash === undefined && me.body.salt === undefined, me.text);
    await s.stop();
  }

  console.log(out.join('\n'));
  const fails = out.filter((l) => l.startsWith('FAIL'));
  console.log(`\n--- ${out.filter((l)=>l.startsWith('PASS')).length} PASS, ${fails.length} FAIL ---`);
  process.exit(fails.length ? 1 : 0);
})().catch((e) => { console.error('PROBE ERROR', e); process.exit(2); });
