async function ownership() {
  const s = await start();
  const alice = await s.signUp('alice@example.com');
  const bob = await s.signUp('bob@example.com');
  const order = (await s.call('POST', '/orders', { token: alice.token, body: { items: ITEM } })).body;
  const asBob = await s.call('GET', '/orders/' + order.id, { token: bob.token });
  ok('a: foreign read 404', asBob.status === 404, 'status=' + asBob.status);
  ok('a: foreign read body', JSON.stringify(asBob.body) === '{"error":"order not found"}', JSON.stringify(asBob.body));
  ok('a: no leak of owner id/order id', !asBob.text.includes(alice.profile.id) && !asBob.text.includes(order.id), asBob.text);
  const own = await s.call('GET', '/orders/' + order.id, { token: alice.token });
  ok('a: owner 200', own.status === 200 && own.body.id === order.id, 'status=' + own.status);
  const adm = await s.call('GET', '/orders/' + order.id, { token: s.adminToken });
  ok('a: admin 200', adm.status === 200 && adm.body.id === order.id, 'status=' + adm.status);
  const unk = await s.call('GET', '/orders/does-not-exist', { token: bob.token });
  ok('a: unknown id -> identical 404', unk.status === 404 && unk.body.error === 'order not found', unk.status + ' ' + JSON.stringify(unk.body));
  ok('a: foreign cancel 404', (await s.call('POST', '/orders/' + order.id + '/cancel', { token: bob.token })).status === 404);
  ok('a: foreign pay 404', (await s.call('POST', '/payments', { token: bob.token, body: { orderId: order.id, amount: 10 } })).status === 404);
  ok('a: foreign ship 403', (await s.call('POST', '/orders/' + order.id + '/ship', { token: bob.token })).status === 403);
  const listed = await s.call('GET', '/orders', { token: bob.token });
  ok('a: foreign order absent from list', listed.body.total === 0, JSON.stringify(listed.body));
  await s.stop();
}
module.exports = { ownership, out, ok, info, start, ITEM };
