'use strict';
const { ok, info, start, ITEM, out } = require('./p1');

async function lifecycle() {
  const s = await start();
  const alice = await s.signUp('alice@example.com');
  const mk = async () => (await s.call('POST', '/orders', { token: alice.token, body: { items: ITEM } })).body;
  const pay = (id) => s.call('POST', '/payments', { token: alice.token, body: { orderId: id, amount: 10 } });
  const cancel = (id, tok) => s.call('POST', '/orders/' + id + '/cancel', { token: tok || alice.token });
  const ship = (id) => s.call('POST', '/orders/' + id + '/ship', { token: s.adminToken });
  const deliver = (id) => s.call('POST', '/orders/' + id + '/deliver', { token: s.adminToken });

  let o = await mk();
  ok('c: ship pending -> 409', (await ship(o.id)).status === 409);
  ok('c: deliver pending -> 409', (await deliver(o.id)).status === 409);
  ok('c: cancel pending -> 200', (await cancel(o.id)).status === 200);
  ok('c: cancel cancelled -> 409', (await cancel(o.id)).status === 409);
  ok('c: pay cancelled -> 409', (await pay(o.id)).status === 409);

  o = await mk();
  ok('c: pay pending -> 201', (await pay(o.id)).status === 201);
  ok('c: cancel paid -> 200 (README allows)', (await cancel(o.id)).status === 200);

  o = await mk(); await pay(o.id);
  ok('c: deliver paid -> 409', (await deliver(o.id)).status === 409);
  ok('c: ship paid -> 200', (await ship(o.id)).status === 200);
  const cs = await cancel(o.id);
  ok('c: cancel SHIPPED -> 409', cs.status === 409, cs.status + ' ' + JSON.stringify(cs.body));
  ok('c: ship shipped -> 409', (await ship(o.id)).status === 409);
  ok('c: deliver shipped -> 200', (await deliver(o.id)).status === 200);
  const cd = await cancel(o.id);
  ok('c: cancel DELIVERED -> 409', cd.status === 409, cd.status + ' ' + JSON.stringify(cd.body));
  ok('c: deliver delivered -> 409', (await deliver(o.id)).status === 409);
  ok('c: still delivered', (await s.call('GET', '/orders/' + o.id, { token: alice.token })).body.status === 'delivered');

  const o2 = await mk();
  const ac = await cancel(o2.id, s.adminToken);
  info('c: ADMIN cancel of a customer order -> ' + ac.status + ' ' + JSON.stringify(ac.body && ac.body.status));
  const o3 = await mk();
