      if (res.status !== 201) { info('d: ' + p + ' x ' + q + ' REJECTED ' + res.status + ' ' + JSON.stringify(res.body)); continue; }
      accepted += 1;
      const cents = Math.round(p * 100) * q;
      const total = res.body.total;
      const raw = (res.text.match(/"total":([^,}]*)/) || [])[1];
