      const pd = await s.call('POST', '/payments', { token: alice.token, body: { orderId: res.body.id, amount: total } });
      if (pd.status !== 201) { bad += 1; ok('d: payment of exact total ' + total, false, pd.status + ' ' + JSON.stringify(pd.body)); }
      const off = await s.call('POST', '/payments', { token: alice.token, body: { orderId: res.body.id, amount: total } });
      if (off.status !== 409) { bad += 1; ok('d: second payment should be 409', false, String(off.status)); }
    }
  }
  ok('d: ' + accepted + ' price x qty combos exact to the cent and payable', bad === 0, 'bad=' + bad);

  const multi = await s.call('POST', '/orders', { token: alice.token, body: { items: [
