  ok('d: raw JSON shows 60.7', /"total":60\.7[,}]/.test(multi.text), multi.text.slice(0, 160));

  const name = (await s.call('POST', '/reports/orders', { token: s.adminToken })).body.name;
  const csv = await s.call('GET', '/reports/' + name, { token: s.adminToken });
  const lines = csv.text.trim().split('\n');
  const bads = lines.slice(1).map((l) => l.split(',')[3]).filter((v) => !/^[0-9]+\.[0-9]{2}$/.test(v));
  ok('d: every CSV total is a plain 2-decimal number (' + (lines.length - 1) + ' rows)', bads.length === 0, bads.join('|'));
  const row = lines.find((l) => l.startsWith(multi.body.id));
  ok('d: CSV total for the multi-line order is 60.70', !!row && row.split(',')[3] === '60.70', String(row));
  ok('d: CSV header unchanged', lines[0] === 'id,userId,status,total,createdAt', lines[0]);
  await s.stop();
}
module.exports = { money };
