'use strict';
const net = require('node:net');

function rawCall(port, line, token) {
  return new Promise((resolve, reject) => {
    const sock = net.connect(port, '127.0.0.1', () => {
      const headers = ['Host: 127.0.0.1', 'Connection: close'];
      if (token) headers.push('Authorization: Bearer ' + token);
      sock.write(line + ' HTTP/1.1' + '\r\n' + headers.join('\r\n') + '\r\n\r\n', 'latin1');
    });
    const chunks = [];
    sock.on('data', (c) => chunks.push(c));
    sock.on('end', () => {
      const raw = Buffer.concat(chunks).toString('latin1');
      const status = Number((raw.match(/^HTTP\/1\.1 (\d+)/) || [])[1]);
      const body = raw.split('\r\n\r\n').slice(1).join('\r\n\r\n');
      resolve({ status, text: body, raw });
    });
    sock.on('error', reject);
    sock.setTimeout(5000, () => { sock.destroy(); resolve({ status: -1, text: '', raw: 'TIMEOUT' }); });
  });
}
module.exports = { rawCall };
