const { createApp } = require(REPO + '/src/app.js');
const PATTERN = /^orders-\d+-[0-9a-f]{6}\.csv$/;
const real = Date.now;

function j(port, m, p, b, t) {
  return new Promise((res) => {
    const pl = b === undefined ? undefined : JSON.stringify(b);
    const h = {}; if (pl) h['content-type'] = 'application/json'; if (t) h.authorization = 'Bearer ' + t;
    const r = http.request({ host: '127.0.0.1', port, method: m, path: p, headers: h, agent: false }, (s) => {
      const c = []; s.on('data', (x) => c.push(x));
      s.on('end', () => { const txt = Buffer.concat(c).toString(); let bb; try { bb = JSON.parse(txt); } catch {} res({ status: s.statusCode, text: txt, body: bb }); });
    });
    r.on('error', () => res({ status: -1, text: '' })); r.end(pl);
  });
}

